const finBounds = fn => nativeFinSummary(fn.declaration, args(fn));
const finComment = fn => {
	const bounds = finBounds(fn);
	return bounds ? `    # Checked Lean Fin bounds: ${bounds}.\n` : "";
};

	const finFunctions = model.surface.functions.filter(fn => finBounds(fn));
	if(finFunctions.length) files["README.md"] += `
Lean Fin n parameters and results are exact Integer values below n. The bundled native library compares each argument with its exact bound, including bounds wider than 64 bits, before any Lean code runs. A non-Integer argument raises TypeError and a negative Integer raises RangeError, as for Nat; an Integer at or above its bound raises RangeError whose message names the Lean parameter and bound. Fin 0 has no values, so every call to a function taking one is rejected. Results are Integer values below their declared bound. Fin inside containers, records, variants, callbacks or reviewed Binding IR is not supported in Ruby gems.

${finFunctions.map(fn => `- ${model.namespace}.${fn.field}: ${finBounds(fn)}`).join("
")}
`;

  assert.match(workflow, /node --test tests/ruby-aliases\.test\.mjs
\s*LEAN_BRIDGE_RUBY_FIN_TEST=1 node --test tests/ruby-fin\.test\.mjs
/);
  assert.match(workflow, /test -s build/aliases/ruby\.json
\s*test -s build/native-fin/ruby\.json
/);
  assert.match(workflow, /consumer_command="\$consumer_command && LEAN_BRIDGE_RUBY_FIN_TEST=1 node --test tests/ruby-fin\.test\.mjs"/);
